PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, student_id TEXT UNIQUE NOT NULL, name TEXT NOT NULL, classroom TEXT NOT NULL, number TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student', house INTEGER, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invites(code TEXT PRIMARY KEY, student_id TEXT UNIQUE NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS quizResults(user_id TEXT PRIMARY KEY REFERENCES users(id), answers TEXT NOT NULL, scores TEXT NOT NULL, tie INTEGER, house INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bookPosts(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS images(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), mime TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activities(id TEXT PRIMARY KEY, name TEXT NOT NULL, is_open INTEGER NOT NULL DEFAULT 0, started INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS prizes(number INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spins(id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES activities(id), user_id TEXT NOT NULL REFERENCES users(id), number INTEGER NOT NULL, UNIQUE(activity_id,user_id));
CREATE TABLE IF NOT EXISTS tickets(code TEXT PRIMARY KEY, spin_id TEXT UNIQUE NOT NULL REFERENCES spins(id), snapshot TEXT NOT NULL, created TEXT NOT NULL, redeemed TEXT, redeemed_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS auth_attempts(key TEXT PRIMARY KEY, count INTEGER NOT NULL, until REAL NOT NULL);
CREATE INDEX IF NOT EXISTS posts_owner ON bookPosts(user_id);

CREATE TABLE IF NOT EXISTS houses(id INTEGER PRIMARY KEY, body TEXT NOT NULL);
